#pragma once
#include "../shared/Types.hpp"
namespace papertrail { class FolderTree { public: /** Constructs an empty root hierarchy. */ FolderTree(); /** Releases all owned folder and entry nodes. */ ~FolderTree(); /** Finds an absolute or relative path. */ bool findPath(const char* path,EntryType& type,FileID& file) const; /** Creates a uniquely named folder. */ StatusCode createFolder(const char* parent,const char* name); /** Inserts a document entry. */ StatusCode insertDocument(const char* parent,FileID file,const char* name); /** Removes an entry from its parent. */ StatusCode removeEntry(const char* path); /** Finds an entry's parent. */ bool getParent(const char* path,char* output,std::size_t capacity) const; /** Lists children in creation order. */ ExplorerListResult listChildren(const char* path) const; /** Moves an entry into bin ownership. */ StatusCode moveToBin(FileID file); /** Restores an entry from bin ownership. */ StatusCode restoreFromBin(FileID file,const char* destination,const char* name); /** Deletes a subtree permanently. */ StatusCode deleteSubtree(const char* path); /** Validates parent and child links. */ DiagnosticResult validate() const; private: struct Node; Node* root_{}; };
}
